class Solution { public int maxProfitAssignment(int[] difficulty,int[] profit,int[] worker){int n=difficulty.length;int[][] jobs=new int[n][2];for(int i=0;i<n;i++){jobs[i][0]=difficulty[i];jobs[i][1]=profit[i];}Arrays.sort(jobs,Comparator.comparingInt(a->a[0]));Arrays.sort(worker);int answer=0,best=0,index=0;for(int ability:worker){while(index<n&&jobs[index][0]<=ability){best=Math.max(best,jobs[index][1]);index++;}answer+=best;}return answer;} }
